import java.io.*
import java.util.*

const val INF = Int.MAX_VALUE / 2

lateinit var eTo: IntArray
lateinit var eCap: IntArray
lateinit var eCost: IntArray
lateinit var eNext: IntArray
lateinit var head: IntArray
var cnt = 0

fun addEdge(u: Int, v: Int, c: Int, w: Int) {
    eTo[cnt] = v; eCap[cnt] = c; eCost[cnt] = w; eNext[cnt] = head[u]; head[u] = cnt; cnt++
    eTo[cnt] = u; eCap[cnt] = 0; eCost[cnt] = -w; eNext[cnt] = head[v]; head[v] = cnt; cnt++
}

fun mcmf(s: Int, t: Int, N: Int): Int {
    var total = 0
    val dist = IntArray(N)
    val inq = BooleanArray(N)
    val pre = IntArray(N)
    val queue = java.util.ArrayDeque<Int>()
    while (true) {
        Arrays.fill(dist, INF)
        Arrays.fill(inq, false)
        Arrays.fill(pre, -1)
        dist[s] = 0
        queue.clear()
        queue.add(s)
        inq[s] = true
        while (queue.isNotEmpty()) {
            val u = queue.poll()
            inq[u] = false
            val du = dist[u]
            var e = head[u]
            while (e != -1) {
                if (eCap[e] > 0) {
                    val v = eTo[e]
                    val nd = du + eCost[e]
                    if (nd < dist[v]) {
                        dist[v] = nd
                        pre[v] = e
                        if (!inq[v]) {
                            inq[v] = true
                            queue.add(v)
                        }
                    }
                }
                e = eNext[e]
            }
        }
        if (dist[t] >= INF) break
        var f = Int.MAX_VALUE
        var v = t
        while (v != s) {
            val e = pre[v]
            if (eCap[e] < f) f = eCap[e]
            v = eTo[e xor 1]
        }
        v = t
        while (v != s) {
            val e = pre[v]
            eCap[e] -= f
            eCap[e xor 1] += f
            v = eTo[e xor 1]
        }
        total += f * dist[t]
    }
    return total
}

fun main() {
    val st = StreamTokenizer(BufferedInputStream(System.`in`))
    fun ni(): Int { st.nextToken(); return st.nval.toInt() }
    val n = ni()
    val m = ni()
    val a = Array(n) { IntArray(m) { ni() } }

    val N = n * m + 2
    val s = 0
    val t = n * m + 1
    val maxEdges = 2 * (n * m + 2 * n * m + 10)
    eTo = IntArray(maxEdges)
    eCap = IntArray(maxEdges)
    eCost = IntArray(maxEdges)
    eNext = IntArray(maxEdges)
    head = IntArray(N) { -1 }
    cnt = 0

    val di = intArrayOf(1, -1, 0, 0)
    val dj = intArrayOf(0, 0, 1, -1)

    for (i in 0 until n) {
        for (j in 0 until m) {
            val id = i * m + j + 1
            if ((i + j) % 2 == 0) {
                addEdge(s, id, 1, 0)
                for (k in 0 until 4) {
                    val ni2 = i + di[k]
                    val nj2 = j + dj[k]
                    if (ni2 in 0 until n && nj2 in 0 until m) {
                        val id2 = ni2 * m + nj2 + 1
                        val w = if (a[i][j] == a[ni2][nj2]) 0 else 1
                        addEdge(id, id2, 1, w)
                    }
                }
            } else {
                addEdge(id, t, 1, 0)
            }
        }
    }

    val res = mcmf(s, t, N)
    println(res)
}
